// Acceptance tests for the change request:
//   "I want to keep track of my clients. Let me add a client with their name and email.
//    Show me all my clients in one list."
//
// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the add flow is
// driven through the form. Seed honours clients: { id, name, email }.
import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test.describe('clients', () => {
  test('lists all seeded clients in one list, each with name and email', async ({ page }) => {
    await resetAndSeed({
      clients: [
        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
        { id: 2, name: 'Globex', email: 'hello@globex.example' },
      ],
    });

    await page.goto('/clients');

    await expect(page.getByTestId('clients-page')).toBeVisible();
    await expect(page.getByTestId('clients-table')).toBeVisible();
    await expect(page.getByTestId('clients-empty')).toHaveCount(0);

    const acme = page.getByTestId('client-row-1');
    await expect(acme).toBeVisible();
    await expect(acme.getByTestId('client-name')).toHaveText('Acme Corp');
    await expect(acme.getByTestId('client-email')).toHaveText('ops@acme.example');

    const globex = page.getByTestId('client-row-2');
    await expect(globex).toBeVisible();
    await expect(globex.getByTestId('client-name')).toHaveText('Globex');
    await expect(globex.getByTestId('client-email')).toHaveText('hello@globex.example');
  });

  test('shows an empty state when there are no clients', async ({ page }) => {
    await resetAndSeed({ clients: [] });

    await page.goto('/clients');

    await expect(page.getByTestId('clients-page')).toBeVisible();
    await expect(page.getByTestId('clients-empty')).toBeVisible();
    await expect(page.getByTestId('client-name')).toHaveCount(0);
  });

  test('adds a client with their name and email through the form', async ({ page }) => {
    await resetAndSeed({ clients: [] });

    await page.goto('/clients');
    await expect(page.getByTestId('clients-empty')).toBeVisible();

    await expect(page.getByTestId('client-form')).toBeVisible();
    await page.getByTestId('client-form-name').fill('Initech');
    await page.getByTestId('client-form-email').fill('accounts@initech.example');
    await page.getByTestId('client-form-submit').click();

    // Reset RESTART IDENTITY + empty seed => the first created client has id 1.
    const row = page.getByTestId('client-row-1');
    await expect(row).toBeVisible();
    await expect(row.getByTestId('client-name')).toHaveText('Initech');
    await expect(row.getByTestId('client-email')).toHaveText('accounts@initech.example');

    await expect(page.getByTestId('clients-empty')).toHaveCount(0);
  });

  test('reaches the clients list from the nav', async ({ page }) => {
    await resetAndSeed({ clients: [] });

    await page.goto('/');
    await expect(page.getByTestId('app-root')).toBeVisible();

    await page.getByTestId('nav-clients').click();

    await expect(page.getByTestId('clients-page')).toBeVisible();
  });
});

import { useInvoices } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
export function InvoiceList({ projectId }: { projectId: number }) {
  const { data: invoices } = useInvoices(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{Number(invoice.amount).toFixed(2)}</td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{total.toFixed(2)}</td>
        </tr>
      </tfoot>
    </table>
  );
}

